<?php
require __DIR__.'/../app/bootstrap.php';refresh_user();require_login('admin');$allowed=['Pending','Processing','Completed','Cancelled'];$filter=$_GET['status']??'';if(!in_array($filter,$allowed,true))$filter='';$q=trim($_GET['q']??'');
if($filter){$stmt=db()->prepare('SELECT j.*,u.email FROM jobs j JOIN users u ON u.id=j.user_id WHERE j.status=? AND (u.email LIKE ? OR j.original_name LIKE ?) ORDER BY j.created_at DESC');$like='%'.$q.'%';$stmt->bind_param('sss',$filter,$like,$like);}else{$stmt=db()->prepare('SELECT j.*,u.email FROM jobs j JOIN users u ON u.id=j.user_id WHERE u.email LIKE ? OR j.original_name LIKE ? ORDER BY j.created_at DESC');$like='%'.$q.'%';$stmt->bind_param('ss',$like,$like);}$stmt->execute();$jobs=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
render_header('Jobs Management','admin');page_title('Jobs Management','Review submissions and keep the print queue moving.');
?><div class="toolbar"><div class="filter-tabs compact"><a class="filter-tab <?=$filter===''?'selected':''?>" href="/admin/jobs.php">All jobs</a><?php foreach($allowed as $s): ?><a class="filter-tab <?=$s===$filter?'selected':''?>" href="/admin/jobs.php?status=<?=e($s)?>"><?=e($s)?></a><?php endforeach; ?></div><form class="search-form" method="get"><input type="hidden" name="status" value="<?=e($filter)?>"><input name="q" value="<?=e($q)?>" placeholder="Search job or client email"><button class="button button-soft button-small">Search</button></form></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>Job</th><th>Document</th><th>Client</th><th>Submitted</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$jobs): ?><tr><td colspan="6"><div class="empty-state"><span>▤</span><strong>No jobs found</strong><small>Try another search or status filter.</small></div></td></tr><?php else: foreach($jobs as $j): ?><tr><td class="job-id">#<?=str_pad((string)$j['id'],5,'0',STR_PAD_LEFT)?></td><td><div class="file-cell"><span class="file-icon">▤</span><span><strong><?=e($j['original_name'])?></strong><small><?=number_format($j['file_size']/1024,0)?> KB · <?=e($j['copies'])?> copy</small></span></div></td><td><?=e($j['email'])?></td><td><?=e(date('M j, Y · g:i a',strtotime($j['created_at'])))?></td><td><?=status_badge($j['status'])?></td><td><a class="button button-small button-soft" href="/admin/job.php?id=<?=(int)$j['id']?>">View details</a></td></tr><?php endforeach; endif; ?></tbody></table></div></div><?php render_footer();
